<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Auto‑Snake</title>
<style>
  body { margin:0; background:#111; display:flex; flex-direction:column; align-items:center; justify-content:center; height:100vh; color:#fff; font-family:sans-serif; }
  #score { margin-bottom:10px; font-size:1.5rem; }
  canvas { background:#000; display:block; }
</style>
</head>
<body>
<div id="score">Score: 0</div>
<canvas id="game" width="600" height="600"></canvas>
<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const cols = 20, rows = 20, cellSize = canvas.width / cols;

  let snake = [{x:10, y:10}];
  let dir = {x:0, y:0};
  let food = randomFood();
  let score = 0;
  let speed = 100; // ms per tick

  function randomFood() {
    let pos;
    do {
      pos = {x: Math.floor(Math.random()*cols), y: Math.floor(Math.random()*rows)};
    } while (snake.some(s => s.x===pos.x && s.y===pos.y));
    return pos;
  }

  function draw() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    // food
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(food.x*cellSize, food.y*cellSize, cellSize, cellSize);
    // snake
    ctx.fillStyle = '#00ff00';
    snake.forEach(seg => ctx.fillRect(seg.x*cellSize, seg.y*cellSize, cellSize, cellSize));
  }

  function step() {
    // auto‑steer toward food
    const head = snake[0];
    let dx = food.x - head.x;
    let dy = food.y - head.y;
    // prioritize horizontal move if not reversing
    if (dx !== 0) {
      if (dx > 0 && dir.x !== -1) dir = {x:1, y:0};
      else if (dx < 0 && dir.x !== 1) dir = {x:-1, y:0};
    }
    if (dy !== 0 && dir.x===0) { // only vertical if not moving horizontally already
      if (dy > 0 && dir.y !== -1) dir = {x:0, y:1};
      else if (dy < 0 && dir.y !== 1) dir = {x:0, y:-1};
    }
    // if still no direction (e.g., blocked), pick any non‑reverse direction
    if (dir.x===0 && dir.y===0) {
      const choices = [{x:1,y:0},{x:-1,y:0},{x:0,y:1},{x:0,y:-1}];
      dir = choices.find(c=>c.x!==-snake[0].x || c.y!==-snake[0].y);
    }

    const newHead = {x: head.x + dir.x, y: head.y + dir.y};

    // wall collision -> reset
    if (newHead.x<0||newHead.x>=cols||newHead.y<0||newHead.y>=rows|| snake.some(s=>s.x===newHead.x && s.y===newHead.y)) {
      reset();
      return;
    }

    snake.unshift(newHead);
    // eat food?
    if (newHead.x===food.x && newHead.y===food.y) {
      score++;
      document.getElementById('score').textContent = 'Score: ' + score;
      food = randomFood();
    } else {
      snake.pop();
    }
    draw();
  }

  function reset() {
    snake = [{x:10, y:10}];
    dir = {x:0, y:0};
    food = randomFood();
    score = 0;
    document.getElementById('score').textContent = 'Score: 0';
  }

  draw();
  setInterval(step, speed);
})();
</script>
</body>
</html>
```

The script moves the snake each tick toward the food by choosing a non‑reverse direction that reduces the Manhattan distance, updating the canvas and score automatically.
